var romanToInt = function(s) {
    const value = {
        I: 1, V: 5, X: 10, L: 50,
        C: 100, D: 500, M: 1000
    };
    let total = 0;
    for (let i = 0; i < s.length; i++) {
        const current = value[s[i]];
        if (i + 1 < s.length && current < value[s[i + 1]]) {
            total -= current;
        } else {
            total += current;
        }
    }
    return total;
};

solution.python:
class Solution:
    def romanToInt(self, s: str) -> int:
        value = {
            'I': 1, 'V': 5, 'X': 10, 'L': 50,
            'C': 100, 'D': 500, 'M': 1000
        }
        total = 0

        for index, symbol in enumerate(s):
            current = value[symbol]
            if index + 1 < len(s) and current < value[s[index + 1]]:
                total -= current
            else:
                total += current

        return total
